{
  "name": "Sunpower CryoTel GT 低温制冷机",
  "name_en": "Sunpower CryoTel GT Cryocooler",
  "manufacturer": "Sunpower",
  "description": "CryoTel GT 是 Sunpower 的一款实验室用闭循环低温制冷机（冷头 + 控制器一体系统）。用于将样品或实验部件冷却到低温并维持设定温度，支持以功率或温度为控制目标的工作模式。设备带有温度设定点、功率设定与限制、恒温器输出、“到达温度”指示（绿色 LED 与 I/O 引脚）以及串行通信与数字 I/O 接口，适用于需要稳定低温环境的实验室应用。",
  "description_en": "The CryoTel GT is a Sunpower laboratory closed-cycle cryocooler (cold head plus controller). It cools samples or components to cryogenic temperatures and maintains setpoints, supporting control by power or by temperature. The unit provides temperature setpoint, power setpoint and limits, a thermostat output, an \"At Temperature\" indicator (green LED and I/O pin), and serial/DIO interfaces for integration into lab setups.",
  "actions": [
    {
      "action_name": "auto-at_temperature_band",
      "description": "get/set 触发“到达温度”指示（绿色 LED 与 I/O 引脚）的温度带（单位：K）。",
      "description_en": "get/set the temperature band (K) that activates the \"At Temperature\" indicator (green LED and I/O pin)."
    },
    {
      "action_name": "auto-control_mode",
      "description": "get/set 冷却器的控制模式（可选：POWER 或 TEMPERATURE）。",
      "description_en": "get/set the cooler control mode (options: ControlMode.POWER or ControlMode.TEMPERATURE)."
    },
    {
      "action_name": "auto-ki",
      "description": "get/set 温度控制环路的积分常数 Ki（用于调节控制环路响应）。",
      "description_en": "get/set the integral constant (Ki) of the temperature control loop."
    },
    {
      "action_name": "auto-kp",
      "description": "get/set 温度控制环路的比例常数 Kp（用于调节控制环路响应）。",
      "description_en": "get/set the proportional constant (Kp) of the temperature control loop."
    },
    {
      "action_name": "auto-power_max",
      "description": "get/set 用户定义的最大输出功率（瓦特）；设备会在必要时自动限制到安全值。",
      "description_en": "get/set the user-defined maximum output power (W); the cooler will automatically cap power to safe limits if needed."
    },
    {
      "action_name": "auto-power_min",
      "description": "get/set 用户定义的最小输出功率（瓦特）；设备会在必要时自动限制到安全值。",
      "description_en": "get/set the user-defined minimum output power (W); the cooler will automatically cap power to safe limits if needed."
    },
    {
      "action_name": "auto-power_setpoint",
      "description": "get/set 功率设定点（瓦特），当控制模式为 POWER 时使用该设定。",
      "description_en": "get/set the power setpoint (W) used when the control mode is set to POWER."
    },
    {
      "action_name": "auto-query",
      "description": "向控制器发送一条查询/命令并返回响应；用于读取或设置控制器变量并获取返回值。",
      "description_en": "Send a query/command string to the controller and return the response; used to read or set controller variables and receive the reply."
    },
    {
      "action_name": "auto-query_multiline",
      "description": "发送会返回多行数据的查询命令，并返回多行响应结果。",
      "description_en": "Send a query that returns multiple lines of data and return the multiline response."
    },
    {
      "action_name": "auto-reset",
      "description": "执行出厂重置，将 CryoTel GT 恢复到出厂默认设置。",
      "description_en": "Reset the CryoTel GT to factory default settings."
    },
    {
      "action_name": "auto-save_control_mode",
      "description": "保存当前的控制模式为默认控制模式（在设备允许的情况下写入控制器）。",
      "description_en": "Save the current control mode as the default control mode in the controller."
    },
    {
      "action_name": "auto-sendcmd",
      "description": "发送原始命令字符串到控制器（不返回多行数据）。",
      "description_en": "Send a raw command string to the controller."
    },
    {
      "action_name": "auto-stop",
      "description": "get/set 装置的停止状态（True=停止/停机，False=启动/运行）。",
      "description_en": "get/set the device stop state (True = stop/shutdown, False = start/run)."
    },
    {
      "action_name": "auto-stop_mode",
      "description": "get/set 停止模式选择（例如：StopMode.HOST 或 StopMode.DIGIO）。",
      "description_en": "get/set the stop mode selection (e.g., StopMode.HOST or StopMode.DIGIO)."
    },
    {
      "action_name": "auto-temperature_setpoint",
      "description": "get/set 温度设定点（开尔文）；当控制模式为 TEMPERATURE 时使用该设定。",
      "description_en": "get/set the temperature setpoint (K) used when the control mode is set to TEMPERATURE."
    },
    {
      "action_name": "auto-thermostat",
      "description": "get/set 恒温器模式（True = 启用恒温器输出，False = 禁用）。",
      "description_en": "get/set the thermostat mode (True = enable thermostat output, False = disable)."
    },
    {
      "action_name": "auto-errors",
      "description": "get 返回当前活动的错误代码列表（若无活动错误返回空列表）。",
      "description_en": "get the list of currently active error codes (returns an empty list if no active errors)."
    },
    {
      "action_name": "auto-power",
      "description": "get 返回当前输出功率（瓦特）。",
      "description_en": "get the current output power (W)."
    },
    {
      "action_name": "auto-power_current_and_limits",
      "description": "get 返回当前功率及在当前温度下的功率上下限（通常为当前最大允许功率、最小允许功率与当前功率）。",
      "description_en": "get the current power and the allowable power limits at the current temperature (typically: maximum allowable power, minimum allowable power, and current power)."
    },
    {
      "action_name": "auto-serial_number",
      "description": "get 返回设备的序列号与固件/修订版本字符串。",
      "description_en": "get the device serial number and revision strings."
    },
    {
      "action_name": "auto-state",
      "description": "get 从控制器读取大多数控制参数及其当前值的列表（直接反映控制器内部状态）。",
      "description_en": "get a list of most control parameters and their current values from the controller (direct representation of controller state)."
    },
    {
      "action_name": "auto-temperature",
      "description": "get 读取当前温度（开尔文）。",
      "description_en": "get the current temperature (K)."
    },
    {
      "action_name": "auto-thermostat_status",
      "description": "get 返回恒温器当前状态（例如：ThermostatStatus.ON 或 ThermostatStatus.OFF）。",
      "description_en": "get the current thermostat status (e.g., ThermostatStatus.ON or ThermostatStatus.OFF)."
    }
  ],
  "tag_hints": [
    "cryocooler",
    "cryogenic cooling",
    "temperature control",
    "power control",
    "PID tuning (Kp/Ki)",
    "serial communication",
    "thermostat output"
  ]
}
